def reject_directory_entry?(entry)
  return true if @filter_site.nil? && entry.end_with?(".")
  return true if entry.end_with?(".")

  included = entry_included?(entry)
  return true if entry_excluded?(entry) && !included
  return true if filtered_symlink?(entry)
  return false if included

  entry_special?(entry) || entry_backup?(entry)
end

def match_string_glob_pattern?(pattern, entry_with_source, entry_is_directory)
  pattern_with_source = join_cached_paths(@filter_source, pattern)
  File.fnmatch?(pattern_with_source, entry_with_source) ||
    entry_with_source.start_with?(pattern_with_source) ||
    (pattern_with_source == "#{entry_with_source}/" if entry_is_directory)
end

